import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    N = int(input_data[0])
    S = input_data[1]
    T = input_data[2]

    # Check if a valid transformation character mapping exists
    mapping = {}
    for s_char, t_char in zip(S, T):
        if s_char in mapping:
            if mapping[s_char] != t_char:
                print(-1)
                return
        else:
            mapping[s_char] = t_char

    # If we need to make changes but all 26 characters are strictly required in the target,
    # any operation will merge two characters permanently, making it impossible to form T.
    if S != T and len(set(T)) == 26:
        print(-1)
        return

    # Build functional graph for necessary character transitions and track in-degrees
    edges = 0
    adj = {}
    in_degree = {}

    for c, target in mapping.items():
        if c != target:
            edges += 1
            adj[c] = target
            in_degree[target] = in_degree.get(target, 0) + 1

    # Count the number of pure cycles in the directed graph
    cycles = 0
    visited = set()

    for node in adj:
        if node not in visited:
            curr = node
            path_list = []
            path_set = set()
            while curr in adj and curr not in visited:
                visited.add(curr)
                path_set.add(curr)
                path_list.append(curr)
                curr = adj[curr]

            # If we loop back to a node in the current traversal path, a cycle is found
            if curr in path_set:
                idx = path_list.index(curr)
                cycle_nodes = path_list[idx:]

                # A cycle is "pure" only if no external edges (tree edges) point into it.
                # If any node in the cycle has an in_degree > 1, an external tree points to it.
                is_pure = True
                for n in cycle_nodes:
                    if in_degree.get(n, 0) > 1:
                        is_pure = False
                        break

                if is_pure:
                    cycles += 1

    # Minimum operations = (number of transition edges) + (number of pure cycles to break)
    print(edges + cycles)

if __name__ == '__main__':
    solve()
